document.querySelectorAll('[data-lab="BM03-I1"]').forEach(root=>{const zh=root.dataset.lang==='zh',get=s=>root.querySelector('[data-field="'+s+'"]'),start=get('start'),end=get('end'),target=[0,0,0,0,0,1,4,10,18,25,18,10,4,1,0,0,0,0,0,0,0],other=[0,0,1,3,6,8,6,3,1,1,3,7,14,20,14,7,3,1,0,0,0],total=target.reduce((a,b)=>a+b,0);get('data').innerHTML=target.map((v,i)=>'<tr><td>'+(i+1)+'</td><td>'+v+'</td><td>'+other[i]+'</td></tr>').join('');function update(changed){let a=Number(start.value),b=Number(end.value);if(a>b){if(changed==='start'){b=a;end.value=b;}else{a=b;start.value=a;}}get('startValue').textContent=a;get('endValue').textContent=b;let mt=0,mo=0;for(let i=a-1;i<b;i++){mt+=target[i];mo+=other[i];}const purity=mt+mo?100*mt/(mt+mo):null,recovery=100*mt/total;const X=i=>75+i*23.25,Y=v=>310-v*8;let grid='';[0,10,20,30].forEach(v=>{grid+='<path d="M75 '+Y(v)+' H540" stroke="#d9dfdc"/><text x="61" y="'+(Y(v)+6)+'" text-anchor="end" font-size="20">'+v+'</text>';});[1,5,10,15,21].forEach(v=>{grid+='<text x="'+X(v-1)+'" y="340" text-anchor="middle" font-size="20">'+v+'</text>';});const curve=arr=>arr.map((v,i)=>X(i)+','+Y(v)).join(' ');get('plot').innerHTML='<rect width="600" height="405" rx="16" fill="#f5f6ee"/><g fill="#153b43" font-family="system-ui,sans-serif"><rect x="'+(X(a-1)-8)+'" y="62" width="'+(X(b-1)-X(a-1)+16)+'" height="248" fill="#168b83" opacity="0.12"/>'+grid+'<path d="M75 60 V310 H540" stroke="#153b43" fill="none"/><polyline points="'+curve(target)+'" stroke="#168b83" stroke-width="4" fill="none"/><polyline points="'+curve(other)+'" stroke="#c46c42" stroke-width="4" fill="none"/><text x="75" y="33" font-size="20">'+(zh?'每管质量 / mg':'Mass per fraction / mg')+'</text><text x="305" y="380" text-anchor="middle" font-size="21">'+(zh?'馏分管号':'Fraction number')+'</text><text x="340" y="34" fill="#168b83" font-size="20">'+(zh?'目标':'Target')+'</text><text x="435" y="34" fill="#c46c42" font-size="20">'+(zh?'其他蛋白':'Other')+'</text></g>';get('result').textContent=zh?'第'+a+'至'+b+'管包含目标'+mt+' mg、其他蛋白'+mo+' mg。'+(purity===null?'未收集到蛋白，纯度无定义。':'目标纯度为'+purity.toFixed(2)+'%。')+'相对于全部'+total+' mg目标，回收率为'+recovery.toFixed(2)+'%。':'Fractions '+a+'–'+b+' contain '+mt+' mg target and '+mo+' mg other protein. '+(purity===null?'No protein is collected, so purity is undefined.':'Target purity is '+purity.toFixed(2)+'%.')+' Recovery from the full '+total+' mg target is '+recovery.toFixed(2)+'%.';}start.addEventListener('input',()=>update('start'));end.addEventListener('input',()=>update('end'));get('reset').addEventListener('click',()=>{start.value=8;end.value=11;update();});update();});